// ============================================================
// CONFIGURAÇÃO E CONSTANTES
// ============================================================
const FILE_TYPES = {
    video: ["mp4", "webm", "avi", "mpg", "mpeg", "mkv", "rm", "rmvb", "mov", "wmv", "asf", "ts", "flv", "3gp", "m4v"],
    audio: ["mp3", "flac", "wav", "ogg", "m4a", "aac", "wma", "alac"],
    image: ["bmp", "jpg", "jpeg", "png", "gif", "svg", "tiff", "ico"],
    code: ["php", "css", "go", "java", "js", "json", "txt", "sh", "html", "xml", "py", "rb", "c", "cpp", "h", "hpp"],
    archive: ["zip", "rar", "tar", "7z", "gz"],
    document: ["pdf", "doc", "docx", "xls", "xlsx", "ppt", "pptx"],
    markdown: ["md"]
};

const GDOC_TYPES = {
    "application/vnd.google-apps.document": { icon: '<i class="bi bi-file-earmark-text"></i>', name: "Google Doc", formats: [{label: "PDF", ext: "pdf"}, {label: "DOCX", ext: "docx"}, {label: "TXT", ext: "txt"}] },
    "application/vnd.google-apps.spreadsheet": { icon: '<i class="bi bi-file-earmark-spreadsheet"></i>', name: "Google Sheet", formats: [{label: "PDF", ext: "pdf"}, {label: "XLSX", ext: "xlsx"}, {label: "CSV", ext: "csv"}] },
    "application/vnd.google-apps.presentation": { icon: '<i class="bi bi-file-earmark-slides"></i>', name: "Google Slides", formats: [{label: "PDF", ext: "pdf"}, {label: "PPTX", ext: "pptx"}] }
};

// ============================================================
// SISTEMA DE COOKIES PARA PERSISTÊNCIA ROBUSTA
// ============================================================
function setCookieData(name, value, days = 365) {
    try {
        const expires = new Date(Date.now() + days * 864e5).toUTCString();
        document.cookie = `${name}=${encodeURIComponent(JSON.stringify(value))}; expires=${expires}; path=/; SameSite=Lax`;
        return true;
    } catch(e) { return false; }
}

function getCookieData(name) {
    try {
        const match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
        if (match) return JSON.parse(decodeURIComponent(match[2]));
    } catch(e) {}
    return null;
}

const GDIUserSystem = {
    currentUser: null,
    init() {
        this.currentUser = this.getCurrentUser();
        if (!this.currentUser) {
            this.currentUser = {
                id: 'user_' + Date.now(),
                name: 'Estudante',
                preferences: { theme: 'dark' },
                notes: {},
                videoProgress: {},
                watchHistory: [],
                completedLessons: {}
            };
            this.saveUser(this.currentUser);
        }
    },
    getCurrentUser() { return getCookieData('gdi-current-user'); },
    saveUser(user) {
        this.currentUser = user;
        return setCookieData('gdi-current-user', user, 365);
    },
    updatePreferences(newPrefs) {
        if (!this.currentUser) return;
        this.currentUser.preferences = { ...this.currentUser.preferences, ...newPrefs };
        this.saveUser(this.currentUser);
    },
    addNote(videoId, note) {
        if (!this.currentUser) return;
        if (!this.currentUser.notes) this.currentUser.notes = {};
        if (!this.currentUser.notes[videoId]) this.currentUser.notes[videoId] = [];
        note.id = 'note_' + Date.now();
        this.currentUser.notes[videoId].push(note);
        this.saveUser(this.currentUser);
    },
    removeNote(videoId, noteId) {
        if (!this.currentUser || !this.currentUser.notes?.[videoId]) return;
        this.currentUser.notes[videoId] = this.currentUser.notes[videoId].filter(n => n.id !== noteId);
        this.saveUser(this.currentUser);
    },
    getNotes(videoId) { return this.currentUser?.notes?.[videoId] || []; },
    saveVideoProgress(videoId, progress) {
        if (!this.currentUser) return;
        if (!this.currentUser.videoProgress) this.currentUser.videoProgress = {};
        if (!this.currentUser.watchHistory) this.currentUser.watchHistory = [];
        this.currentUser.videoProgress[videoId] = { ...progress, updatedAt: new Date().toISOString() };
        
        const historyEntry = { videoId, name: progress.name, progress: progress.duration > 0 ? progress.currentTime / progress.duration : 0, url: progress.url };
        this.currentUser.watchHistory = this.currentUser.watchHistory.filter(item => item.videoId !== videoId);
        this.currentUser.watchHistory.unshift(historyEntry);
        this.currentUser.watchHistory = this.currentUser.watchHistory.slice(0, 20);
        this.saveUser(this.currentUser);
    },
    getVideoProgress(videoId) { return this.currentUser?.videoProgress?.[videoId] || null; },
    getContinueWatching() {
        if (!this.currentUser || !this.currentUser.watchHistory) return [];
        return this.currentUser.watchHistory.filter(item => item.progress > 0.02 && item.progress < 0.95).slice(0, 6);
    }
};

