// ============================================================
// FUNÇÕES UTILITÁRIAS E RENDERIZAÇÃO
// ============================================================
function isFileType(i, e) { return FILE_TYPES[e] && FILE_TYPES[e].includes(i?.toLowerCase()); }
function getFileIcon(i) {
    const e = i?.toLowerCase();
    return isFileType(e, "video") ? '<i class="bi bi-camera-video-fill text-primary"></i>' :
           isFileType(e, "audio") ? '<i class="bi bi-music-note-beamed text-pink"></i>' :
           isFileType(e, "image") ? '<i class="bi bi-image text-success"></i>' :
           isFileType(e, "archive") ? '<i class="bi bi-file-earmark-zip-fill text-warning"></i>' :
           e === "pdf" ? '<i class="bi bi-file-earmark-pdf-fill text-danger"></i>' : '<i class="bi bi-file-earmark"></i>';
}
function escHtml(i) { return String(i || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#x27;"); }
function trimChar(i, e) { return e ? i.replace(new RegExp("^\\" + e + "+|\\" + e + "+$", "g"), "") : i.trim(); }
function applyTheme(i) {
    document.documentElement.setAttribute("data-bs-theme", i);
    const e = document.getElementById("theme-icon");
    e && (e.className = i === "dark" ? "bi bi-moon-stars" : "bi bi-sun");
}
function toggleTheme() {
    const next = (document.documentElement.getAttribute("data-bs-theme") || "dark") === "dark" ? "light" : "dark";
    applyTheme(next);
    GDIUserSystem.updatePreferences({ theme: next });
}
function formatFileSize(i) {
    const e = Number(i);
    return isNaN(e) || e < 0 ? "" : e >= 1073741824 ? (e / 1073741824).toFixed(2) + " GB" : (e / 1048576).toFixed(2) + " MB";
}
function formatTime(seconds) {
    const m = Math.floor(seconds / 60), s = Math.floor(seconds % 60);
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function init() {
    const UI = window.UI || {};
    document.siteName = $("title").html();
    $("body").html(`
        <div id="nav"></div>
        <div id="content" style="padding-top:76px; padding-bottom:100px;"></div>
        <div id="gdi-toast-container"></div>
        <footer class="text-center py-4 text-muted" style="font-size:13px;border-top:1px solid var(--gdi-border);">
            <span>&copy; ${new Date().getFullYear()} ${UI.company_name || 'Drive'} &middot; Plataforma de Estudos</span>
        </footer>
    `);
}

function nav() {
    const t = window.current_drive_order || 0, n = window.drive_names?.[t] || "Drive", UI = window.UI || {};
    let l = "";
    (window.drive_names || []).forEach((r, p) => { l += `<li><a class="dropdown-item${p === t ? " active" : ""}" href="/${p}:/">${r}</a></li>`; });
    
    $("#nav").html(`
        <nav class="gdi-nav">
          <div class="gdi-nav-inner">
            <a class="gdi-logo" href="/${t}:/"><i class="bi bi-mortarboard-fill"></i> <span>${UI.logo_link_name || 'Academia'}</span></a>
            <div class="d-flex align-items-center gap-2">
              <div class="dropdown">
                <button class="gdi-btn gdi-btn-ghost dropdown-toggle" type="button" data-bs-toggle="dropdown">${escHtml(n)}</button>
                <ul class="dropdown-menu dropdown-menu-end shadow">${l}</ul>
              </div>
              <button class="gdi-btn gdi-btn-ghost" onclick="toggleTheme()"><i class="bi bi-moon-stars" id="theme-icon"></i></button>
            </div>
          </div>
        </nav>
    `);
    applyTheme(GDIUserSystem.currentUser?.preferences?.theme || 'dark');
}

function render(path) {
    if (path.indexOf("?") >= 0) path = path.substr(0, path.indexOf("?"));
    nav();
    if (path.includes("/fallback") || path.slice(-1) == "/" || /\/\d+:$/.test(path)) {
        list(path);
    } else {
        file(path);
    }
}

// ============================================================
// LISTAGEM E BANNER
// ============================================================
function list(i) {
    const n = window.location.pathname, a = trimChar(n, "/").split("/");
    let c = "/", l = '<li><a href="/">Início</a></li><li class="gdi-bc-sep">/</li>';
    if (a.length > 1) {
        for (const p in a) {
            const g = a[p]; let f = decodeURIComponent(g);
            c += g + "/";
            l += `<li><a href="${c}">${escHtml(f)}</a></li><li class="gdi-bc-sep">/</li>`;
        }
    }
    
    $("#content").html(`
        <div class="gdi-wrap">
          <div id="continue-watching-container"></div>
          <div class="gdi-breadcrumb-wrap"><ol class="gdi-bc">${l}</ol></div>
          <div class="gdi-panel">
            <div class="gdi-list-header"><span></span><span>Nome do Arquivo / Aula</span><span>Tamanho</span><span>Modificado</span><span class="text-end">Ações</span></div>
            <div id="list"><div class="text-center py-5"><div class="spinner-border text-primary"></div></div></div>
          </div>
        </div>
    `);
    
    renderContinueWatchingBanner();
    
    fetch(i, { method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({type: "folder"}) })
        .then(res => res.json())
        .then(data => {
            const files = data?.data?.files || [];
            let html = "";
            files.forEach(s => {
                const isFolder = s.mimeType == "application/vnd.google-apps.folder";
                const rowUrl = isFolder ? i + encodeURIComponent(s.name) + "/" : i + encodeURIComponent(s.name) + "?a=view";
                const isCompleted = GDIUserSystem.currentUser?.completedLessons?.[s.id] ? 'checked' : '';
                
                html += `
                <div class="gdi-row">
                  <span>${isFolder ? '<i class="bi bi-folder-fill text-warning"></i>' : getFileIcon(s.fileExtension)}</span>
                  <span class="gdi-row-name"><a href="${rowUrl}" class="text-decoration-none text-reset">${escHtml(s.name)}</a></span>
                  <span class="text-muted" style="font-size:12px;">${formatFileSize(s.size)}</span>
                  <span class="text-muted" style="font-size:12px;">${new Date(s.modifiedTime).toLocaleDateString()}</span>
                  <span class="text-end d-flex align-items-center justify-content-end gap-2">
                    ${!isFolder ? `<input class="form-check-input" type="checkbox" ${isCompleted} onchange="toggleLesson('${s.id}', this)" title="Concluída">` : ''}
                    <a class="gdi-btn gdi-btn-ghost py-1 px-2" href="${window.location.origin + s.link}" download><i class="bi bi-download"></i></a>
                  </span>
                </div>`;
            });
            $("#list").html(html || '<div class="text-center py-4 text-muted">Pasta vazia</div>');
        }).catch(() => { $("#list").html('<div class="text-center py-4 text-danger">Erro ao carregar pasta</div>'); });
}

function renderContinueWatchingBanner() {
    const history = GDIUserSystem.getContinueWatching();
    if (!history.length) return;
    let html = `<div class="gdi-panel p-4 mb-4" style="background:linear-gradient(135deg, rgba(37,99,235,0.1), transparent);">
        <h5 class="mb-3 fw-bold" style="font-size:15px;"><i class="bi bi-play-circle-fill text-primary me-2"></i>Continuar Assistindo</h5>
        <div class="d-flex gap-3 overflow-x-auto pb-2">`;
    history.forEach(item => {
        const pct = Math.round((item.progress || 0) * 100);
        html += `<div class="p-3 rounded flex-shrink-0" style="width:220px;background:var(--gdi-surface-hover);cursor:pointer;" onclick="window.location.href='${item.url}'">
            <div class="fw-semibold text-truncate mb-2" style="font-size:13px;">${escHtml(item.name)}</div>
            <div class="progress mb-2" style="height:4px;"><div class="progress-bar bg-primary" style="width:${pct}%"></div></div>
            <span class="text-muted" style="font-size:11px;">${pct}% concluído</span>
        </div>`;
    });
    html += `</div></div>`;
    document.getElementById('continue-watching-container').innerHTML = html;
}

function toggleLesson(id, checkbox) {
    if (!GDIUserSystem.currentUser.completedLessons) GDIUserSystem.currentUser.completedLessons = {};
    GDIUserSystem.currentUser.completedLessons[id] = checkbox.checked;
    GDIUserSystem.saveUser(GDIUserSystem.currentUser);
}

// ============================================================
// VISUALIZADORES E PLAYER DE VÍDEO
// ============================================================
function file(path) {
    $("#content").html('<div class="text-center py-5"><div class="spinner-border text-primary"></div></div>');
    fetch("", { method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({path: path.split("?")[0]}) })
        .then(r => r.json())
        .then(i => {
            const streamUrl = window.location.origin + i.link;
            const isVideo = FILE_TYPES.video.includes(i.fileExtension) || i.mimeType?.includes("video");
            
            if (isVideo) {
                file_video(i.name, streamUrl, i.id);
            } else {
                $("#content").html(`<div class="gdi-wrap"><div class="gdi-viewer-card"><h4>${escHtml(i.name)}</h4><a href="${streamUrl}" class="gdi-btn gdi-btn-primary mt-3" download>Baixar Arquivo</a></div></div>`);
            }
        }).catch(() => { $("#content").html('<div class="gdi-wrap text-center py-5">Erro ao carregar arquivo.</div>'); });
}

function file_video(name, streamUrl, fileId) {
    $("#content").html(`
        <div class="gdi-wrap">
          <div class="row">
            <div class="col-lg-8 mb-4">
              <div class="gdi-panel overflow-hidden"><video id="player" controls autoplay style="width:100%;max-height:500px;background:#000;"><source src="${streamUrl}" type="video/mp4"></video></div>
              <div class="gdi-panel p-4 mt-3">
                <h5 class="mb-3" style="font-size:15px;"><i class="bi bi-journal-text text-primary me-2"></i>Anotações</h5>
                <div class="d-flex gap-2 mb-3">
                  <input id="gdi-note-input" type="form-control" class="form-control bg-dark text-light border-secondary" placeholder="Nota no minuto atual..." onkeypress="if(event.key==='Enter')addNote('${fileId}')">
                  <button class="gdi-btn gdi-btn-primary" onclick="addNote('${fileId}')"><i class="bi bi-plus-lg"></i></button>
                </div>
                <div id="gdi-notes-list" class="d-flex flex-column gap-2"></div>
              </div>
            </div>
            <div class="col-lg-4">
              <div class="gdi-panel p-3">
                <h6 class="fw-bold mb-3" style="font-size:14px;"><i class="bi bi-collection-play me-2"></i>Aula Atual: ${escHtml(name)}</h6>
                <a href="javascript:history.back()" class="gdi-btn gdi-btn-ghost w-100 text-center"><i class="bi bi-arrow-left"></i> Voltar à Pasta</a>
              </div>
            </div>
          </div>
        </div>
    `);

    setTimeout(() => {
        const player = document.getElementById('player');
        window._gdiPlayerInstance = player;
        
        const saved = GDIUserSystem.getVideoProgress(fileId);
        if (saved && saved.currentTime > 5) player.currentTime = saved.currentTime;

        setInterval(() => {
            if (player.currentTime > 0 && player.duration > 0) {
                GDIUserSystem.saveVideoProgress(fileId, { name, currentTime: player.currentTime, duration: player.duration, url: window.location.href });
            }
        }, 4000);

        loadNotesUI(fileId);
    }, 200);
}

function addNote(fileId) {
    const input = document.getElementById('gdi-note-input');
    if (!input || !input.value.trim()) return;
    const player = window._gdiPlayerInstance;
    const time = player ? player.currentTime : 0;
    
    GDIUserSystem.addNote(fileId, { text: input.value.trim(), timestamp: time, formattedTime: formatTime(time) });
    input.value = '';
    loadNotesUI(fileId);
}

function loadNotesUI(fileId) {
    const box = document.getElementById('gdi-notes-list');
    if (!box) return;
    const notes = GDIUserSystem.getNotes(fileId);
    if (!notes.length) { box.innerHTML = '<span class="text-muted" style="font-size:12px;">Nenhuma anotação.</span>'; return; }
    
    box.innerHTML = notes.map(n => `
        <div class="p-2 rounded d-flex justify-content-between align-items-center" style="background:var(--gdi-surface-hover);">
          <div><button class="badge bg-primary border-0 mb-1" onclick="document.getElementById('player').currentTime=${n.timestamp}">${n.formattedTime}</button><div style="font-size:12px;">${escHtml(n.text)}</div></div>
          <button class="btn btn-sm text-danger" onclick="GDIUserSystem.removeNote('${fileId}','${n.id}');loadNotesUI('${fileId}')"><i class="bi bi-trash"></i></button>
        </div>
    `).join('');
}

// ============================================================
// POMODORO FLUTUANTE
// ============================================================
function initPomodoro() {
    if (document.getElementById('gdi-pom-root')) return;
    const root = document.createElement('div');
    root.id = 'gdi-pom-root';
    root.style.cssText = "position:fixed;bottom:24px;right:24px;z-index:99999;";
    root.innerHTML = `
        <div id="gdi-pom-fab" style="width:48px;height:48px;border-radius:50%;background:var(--gdi-surface);border:1.5px solid var(--gdi-border);box-shadow:var(--gdi-shadow);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:20px;">🍅</div>
        <div id="gdi-pom-panel" style="display:none;position:absolute;bottom:60px;right:0;width:220px;background:var(--gdi-surface);border:1.5px solid var(--gdi-border);border-radius:12px;padding:16px;box-shadow:var(--gdi-shadow);">
            <div class="text-center fw-bold text-primary mb-2" style="font-size:11px;">FOCO ESTUDOS</div>
            <div class="text-center fw-bold mb-3" id="pom-time" style="font-size:32px;">25:00</div>
            <button class="gdi-btn gdi-btn-primary w-100" id="pom-toggle">Iniciar</button>
        </div>
    `;
    document.body.appendChild(root);
    
    let secs = 1500, active = false, timer = null;
    document.getElementById('gdi-pom-fab').onclick = () => {
        const p = document.getElementById('gdi-pom-panel');
        p.style.display = p.style.display === 'none' ? 'block' : 'none';
    };
    
    document.getElementById('pom-toggle').onclick = () => {
        active = !active;
        document.getElementById('pom-toggle').textContent = active ? 'Pausar' : 'Iniciar';
        if (active) {
            timer = setInterval(() => {
                if (secs > 0) {
                    secs--;
                    const m = Math.floor(secs/60), s = secs%60;
                    document.getElementById('pom-time').textContent = `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
                } else {
                    clearInterval(timer); active = false; alert('Pomodoro finalizado!'); secs = 1500;
                }
            }, 1000);
        } else { clearInterval(timer); }
    };
}

// Inicializador Principal
$(function() {
    init();
    GDIUserSystem.init();
    render(window.location.pathname);
    initPomodoro();
});
window.onpopstate = () => render(window.location.pathname);
